def vram_by_phase(path):
    """Parse vram.txt, which records one memory.used sample per phase."""
    values = {}
    if not path.exists():
        return values
    current = None
    for line in path.read_text().splitlines():
        line = line.strip()
        m = re.match(r"^==\s*(\S+)\s*\(", line)
        if m:
            current = m.group(1)
            continue
        vm = re.match(r"^(\d+)\s*MiB,", line)
        if vm and current:
            values[current] = int(vm.group(1))
    return values


